import{_ as a,o as s,c as t,a3 as o}from"./chunks/framework.DH50UWNB.js";const p=JSON.parse('{"title":"Security and privacy","description":"What leaves your Wake installation, what your agents send to your Wake, and how Wake keeps tokens, passwords, secrets and evidence files.","frontmatter":{"description":"What leaves your Wake installation, what your agents send to your Wake, and how Wake keeps tokens, passwords, secrets and evidence files."},"headers":[],"relativePath":"reference/security.md","filePath":"reference/security.md","lastUpdated":1794486787000}'),n={name:"reference/security.md"};function r(i,e,d,l,h,c){return s(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="security-and-privacy" tabindex="-1">Security and privacy <a class="header-anchor" href="#security-and-privacy" aria-label="Permalink to &quot;Security and privacy&quot;">​</a></h1><p>This page says in one place what leaves your installation, what your agents send to your own Wake, and how Wake keeps tokens, passwords and evidence files.</p><h2 id="calls-outside-your-installation" tabindex="-1">Calls outside your installation <a class="header-anchor" href="#calls-outside-your-installation" aria-label="Permalink to &quot;Calls outside your installation&quot;">​</a></h2><p>Wake has no telemetry and no analytics, and its pages load nothing from another site. It calls out in these cases only:</p><ul><li><strong>Release checks to GitHub.</strong> The server asks GitHub for the newest release when it starts and every 12 hours, sending only a <code>User-Agent: wake-server/&lt;version&gt;</code> header. <code>wake-server status</code> and the <code>wake</code> CLI ask too; the CLI at most once a day and never in CI. To turn them off, see <a href="/wake-dist/docs/run/upgrade#how-you-hear-of-a-new-release">How you hear of a new release</a>.</li><li><strong>Downloads.</strong> The installer, <code>wake-server upgrade</code>, the daily automatic upgrade and <code>wake upgrade</code> download releases from GitHub and images from <code>ghcr.io</code>; the installer checks the release files&#39; signature first (<a href="/wake-dist/docs/reference/verify-installer">Verify a download</a>).</li><li><strong>Sign-in providers.</strong> When an owner turns on GitHub, Google, Microsoft or another OpenID Connect provider, the server talks to that provider during a sign-in; see <a href="/wake-dist/docs/run/sign-in-providers">Sign-in providers</a>.</li><li><strong>Agent details.</strong> When an agent signs in with a web address as its identity, the server reads that address&#39;s public description, at most 5 KB, and only from public addresses.</li></ul><p>Claude Code installs the <code>wake</code> plugin from Wake&#39;s public repository on GitHub; see <a href="/wake-dist/docs/agents/claude-code">Claude Code</a>.</p><h2 id="what-your-agents-send-to-your-wake" tabindex="-1">What your agents send to your Wake <a class="header-anchor" href="#what-your-agents-send-to-your-wake" aria-label="Permalink to &quot;What your agents send to your Wake&quot;">​</a></h2><p>The agent hooks send to your own Wake, never anywhere else:</p><ul><li>after each tool call, the tool&#39;s name and the session&#39;s new commits: each commit&#39;s id, subject, time, and the paths of its changed files with their line counts;</li><li>never the tool&#39;s arguments or its output.</li></ul><p>The agent&#39;s MCP calls send what the agent writes on purpose: claims, progress notes, verification, and evidence.</p><h2 id="tokens-on-your-machine" tabindex="-1">Tokens on your machine <a class="header-anchor" href="#tokens-on-your-machine" aria-label="Permalink to &quot;Tokens on your machine&quot;">​</a></h2><p>The CLI keeps its token in your system&#39;s keychain. Where none is available, such as Linux without a Secret Service or WSL, it keeps it in <code>~/.config/wake/credentials.json</code> (under <code>XDG_CONFIG_HOME</code> when you set it), which only you can read (mode <code>0600</code>, in a folder only you can open). Files Wake writes into a repository never hold a token.</p><h2 id="secrets-and-passwords-on-the-server" tabindex="-1">Secrets and passwords on the server <a class="header-anchor" href="#secrets-and-passwords-on-the-server" aria-label="Permalink to &quot;Secrets and passwords on the server&quot;">​</a></h2><ul><li>Sessions, personal access tokens, sign-in codes, OAuth tokens and invitation links are random 256-bit values. The server stores only their SHA-256 hash, and shows a token once, when you create it.</li><li>Passwords are stored as scrypt hashes with a random salt.</li><li>The request log holds the method, the path without its query, the status and the duration; never a token or a password.</li></ul><h2 id="evidence-files" tabindex="-1">Evidence files <a class="header-anchor" href="#evidence-files" aria-label="Permalink to &quot;Evidence files&quot;">​</a></h2><p>Evidence files never pass through the server. It signs a short-lived address (10 minutes to upload, 5 to download) and the file goes straight between your machine and the storage. The bundled storage runs inside the installation; see <a href="/wake-dist/docs/run/evidence-storage">Evidence storage</a>.</p><h2 id="which-address-it-answers-on" tabindex="-1">Which address it answers on <a class="header-anchor" href="#which-address-it-answers-on" aria-label="Permalink to &quot;Which address it answers on&quot;">​</a></h2><p>A local installation answers only on this machine: <code>127.0.0.1:8080</code> for the web app and API and <code>127.0.0.1:8081</code> for evidence files. Nobody else on your network can reach it. An installation with <code>--domain</code> answers on ports 80 and 443 with HTTPS, and sign-up then needs an invitation; see <a href="/wake-dist/docs/start/install#who-can-reach-it">Who can reach it</a>.</p><h2 id="report-a-vulnerability" tabindex="-1">Report a vulnerability <a class="header-anchor" href="#report-a-vulnerability" aria-label="Permalink to &quot;Report a vulnerability&quot;">​</a></h2><p>Report it privately, never in public: see <a href="/wake-dist/docs/reference/help">Get help</a>.</p>',20)])])}const y=a(n,[["render",r]]);export{p as __pageData,y as default};
